package com.college.notes.service;
import com.college.notes.dto.NoteDtos.NoteResponse; import com.college.notes.entity.*; import com.college.notes.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*; import java.util.UUID;
@Service public class NoteService { private final NoteRepository notes; private final SubjectRepository subjects; private final AccessRequestRepository requests; private final CurrentUser current; private final Path root; public NoteService(NoteRepository n,SubjectRepository s,AccessRequestRepository r,CurrentUser c,@Value("${app.upload-dir}") String dir){notes=n;subjects=s;requests=r;current=c;root=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(Exception e){throw new RuntimeException(e);}}
 @Transactional public NoteResponse upload(String title,String desc,Integer unit,Long subjectId,MultipartFile file){User f=current.get();if(f.getRole()!=Role.FACULTY)throw new IllegalArgumentException("Only faculty can upload notes");Subject sub=subjects.findById(subjectId).orElseThrow(()->new IllegalArgumentException("Subject not found"));if(!sub.getFaculty().getId().equals(f.getId()))throw new IllegalArgumentException("You can upload only to your subjects");if(file.isEmpty())throw new IllegalArgumentException("File is required");String type=file.getContentType()==null?"application/octet-stream":file.getContentType();if(!(type.equals("application/pdf")||type.startsWith("image/")))throw new IllegalArgumentException("Only PDF and image files are allowed");String stored=UUID.randomUUID()+"_"+Paths.get(file.getOriginalFilename()==null?"file":file.getOriginalFilename()).getFileName();try{Files.copy(file.getInputStream(),root.resolve(stored),StandardCopyOption.REPLACE_EXISTING);}catch(Exception e){throw new RuntimeException("Could not save file");}Note n=new Note();n.setTitle(title);n.setDescription(desc);n.setUnit(unit);n.setFileName(file.getOriginalFilename());n.setStoredFileName(stored);n.setFileType(type);n.setFileSize(file.getSize());n.setSubject(sub);n.setFaculty(f);return map(notes.save(n));}
 public List<NoteResponse> visible(String q,Long subjectId){User u=current.get();List<Note> list;if(u.getRole()==Role.FACULTY)list=notes.searchForFaculty(u.getId(),q==null?"":q,subjectId);else {Set<Long> subjectIds=new HashSet<>();requests.findByStudentIdOrderByRequestDateDesc(u.getId()).stream().filter(x->x.getStatus()==RequestStatus.ACCEPTED).forEach(x->subjectIds.add(x.getSubject().getId()));list=notes.search(q==null?"":q,subjectId).stream().filter(n->subjectIds.contains(n.getSubject().getId())).toList();}return list.stream().map(this::map).toList();}
 public Resource file(Long id){User u=current.get();Note n=notes.findById(id).orElseThrow();if(u.getRole()!=Role.FACULTY&&!requests.existsByStudentIdAndFacultyIdAndSubjectIdAndStatus(u.getId(),n.getFaculty().getId(),n.getSubject().getId(),RequestStatus.ACCEPTED))throw new org.springframework.security.access.AccessDeniedException("Access not approved");try{return new UrlResource(root.resolve(n.getStoredFileName()).toUri());}catch(Exception e){throw new RuntimeException(e);}}
 public List<NoteResponse> mine(){User u=current.get();return notes.findByFacultyId(u.getId()).stream().map(this::map).toList();}
 public void delete(Long id){User u=current.get();Note n=notes.findById(id).orElseThrow();if(!n.getFaculty().getId().equals(u.getId()))throw new org.springframework.security.access.AccessDeniedException("Not your note");try{Files.deleteIfExists(root.resolve(n.getStoredFileName()));}catch(Exception ignored){}notes.delete(n);}
 private NoteResponse map(Note n){return new NoteResponse(n.getId(),n.getTitle(),n.getDescription(),n.getUnit(),n.getFileName(),n.getFileType(),n.getFileSize(),n.getUploadedAt().toString(),n.getSubject().getId(),n.getSubject().getName(),n.getFaculty().getId(),n.getFaculty().getName());}
}
